/**
 * Which state or territory a coordinate falls in.
 *
 * Used to tag archived incidents so the logs page can filter by state.
 * Most sources are NSW-only, but the national ones (LiveTraffic works,
 * FIRMS hotspots) and ACT Ambulance span several, and nothing upstream
 * reliably says which — the coordinate is the only trustworthy signal.
 *
 * Rings come from the same ArcGIS "State Boundaries" service as
 * lib/australiaMask.ts, per jurisdiction this time, simplified at
 * 0.02 deg with slivers under ~1 km2 dropped. Unlike that mask these are
 * NOT buffered outward: buffering would make neighbouring states overlap
 * and a point near a border could land in either. Interior borders stay
 * sharp, and coastal slop is handled by the fallback below instead.
 *
 * Two passes:
 *   1. exact point-in-polygon — the answer for anything on land;
 *   2. nearest boundary within 0.12 deg (~13 km) — catches a detection
 *      just offshore, or one nudged out by the simplification, and
 *      assigns it to the state it actually sits against.
 * Anything further out than that returns null, which the logs page shows
 * as an unknown state rather than guessing.
 */

export type AuState = 'NSW' | 'VIC' | 'QLD' | 'SA' | 'WA' | 'TAS' | 'NT' | 'ACT';

/** Display order — most populous first, territories last. */
export const AU_STATES: readonly AuState[] = ['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'];

/**
 * Order the rings are TESTED in, which is not the display order.
 *
 * Only exterior rings are stored, so an enclave is contained by the ring
 * of the state around it: every ACT coordinate also falls inside the NSW
 * exterior. Testing the enclave first resolves that — Canberra answers
 * ACT, and a point in NSW is unaffected because it was never inside the
 * ACT ring to begin with.
 *
 * (Jervis Bay is the other hole in NSW. It is an external territory, not
 * one of the eight, so it has no rings here and resolves to the NSW that
 * surrounds it — which is the useful answer for a logs filter.)
 */
const RESOLVE_ORDER: readonly AuState[] = ['ACT', 'NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT'];

/** How far offshore a point may sit and still be attributed (degrees). */
const COAST_TOLERANCE_DEG = 0.12;

type Ring = ReadonlyArray<readonly [number, number]>;

